const organizations=ref<Org[]>([]),users=ref<UserItem[]>([]),ruleVersions=ref<RuleVersion[]>([]),selectedVersion=ref<RuleVersion|null>(null),rules=ref<RuleItem[]>([]),audit=ref<AuditItem[]>([]),settlements=ref<Settlement[]>([]),settlementCorrections=ref<SettlementCorrection[]>([])
const selectedDossier=ref<Dossier|null>(null),incidentReport=ref<IncidentReport|null>(null),openDossiers=ref<DossierSummary[]>([])
const scheduleFilter=reactive({from:dateOffset(0),to:dateOffset(0)}),scheduleForm=reactive({from:dateOffset(1),to:dateOffset(1),shiftCode:'DAY',userIds:[] as string[],lineId:'',stationIds:[] as string[],publish:true,reason:''})
const scheduleDetailFilter=reactive(emptyScheduleFilters()),scheduleLoading=ref(false),schedulePage=ref(1)
