const incidentFilter=reactive({from:'',to:'',keyword:'',lineId:'',status:'ALL',equipmentIds:[] as string[]})
const incidentLoading=ref(false),incidentError=ref(''),incidentPage=ref(0),incidentTotal=ref(0),incidentSummary=ref({open:0,archived:0,voided:0}),incidentApplied=ref(''),incidentExporting=ref(false)
