const equipmentFilter=reactive({orgUnitId:'',lineId:'',stationId:'',status:'',name:''})
const userForm=reactive({employeeNo:'',displayName:'',orgUnitId:''}),roleDraft=reactive<Record<string,string>>({})
const lineForm=reactive({teamId:'',code:'',name:''}),stationForm=reactive({lineId:'',code:'',name:''}),equipmentForm=reactive({code:'',name:'',category:'',orgUnitId:'',lineId:'',stationId:''})
const editingLineId=ref(''),lineDraft=reactive({code:'',name:'',status:'ACTIVE',version:0})
const editingStationId=ref(''),stationDraft=reactive({code:'',name:'',status:'ACTIVE',version:0})
const editingEquipmentId=ref(''),equipmentDraft=reactive({code:'',name:'',category:'',orgUnitId:'',lineId:'',stationId:'',status:'ACTIVE',version:0})
