const calendarForm=reactive({date:new Date().toISOString().slice(0,10),dayType:'HOLIDAY',name:''})
const versionName=ref(''),ruleForm=reactive({code:'',title:'',type:'BONUS',score:1,monthlyCap:20,effectiveFrom:new Date().toISOString().slice(0,10),effectiveTo:''})

const isScored=computed(()=>me.value?.roles.some(r=>r==='TECHNICIAN'||r==='ASSISTANT_ENGINEER')||false)
const isAssistant=computed(()=>me.value?.roles.includes('ASSISTANT_ENGINEER')||false)
const isSupervisor=computed(()=>me.value?.roles.includes('SUPERVISOR')||false)
const isManager=computed(()=>me.value?.roles.includes('DEPARTMENT_MANAGER')||false)
const isAdmin=computed(()=>me.value?.administrator||false)
const roleText=computed(()=>me.value?.roles.map(r=>roleNames[r]||r).join('、')||'')
const navigation=computed(()=>{const result:Array<{key:Page;label:string;mark:string}>=[{key:'dashboard',label:'工作台',mark:'⌂'},{key:'tasks',label:'我的待办',mark:'待'},{key:'messages',label:'消息中心',mark:'信'}];if(isScored.value||isSupervisor.value||isManager.value)result.push({key:'performance',label:'绩效统计',mark:'绩'});if(isAssistant.value||isSupervisor.value||isManager.value)result.push({key:'schedule',label:'责任排班',mark:'日'},{key:'incidents',label:'设备异常',mark:'异'});if(isSupervisor.value||isManager.value)result.push({key:'settlement',label:'月度封存',mark:'封'});if(isManager.value||isAdmin.value)result.push({key:'organization',label:'人员组织',mark:'人'});if(isAdmin.value)result.push({key:'equipment',label:'设备台账',mark:'设'});if(isManager.value||isAdmin.value)result.push({key:'rules',label:'积分规则',mark:'规'});if(isAdmin.value)result.push({key:'audit',label:'操作审计',mark:'审'});return result})
const eligiblePeople=computed(()=>directory.value.filter(p=>p.roles.some(r=>r==='TECHNICIAN'||r==='ASSISTANT_ENGINEER')))
const scheduleStations=computed(()=>catalog.value.stations.filter(s=>s.lineId===scheduleForm.lineId))
const deviceLines=computed(()=>catalog.value.lines.filter(l=>!equipmentForm.orgUnitId||l.teamId===equipmentForm.orgUnitId))
const deviceStations=computed(()=>catalog.value.stations.filter(s=>s.lineId===equipmentForm.lineId))
const editDeviceLines=computed(()=>catalog.value.lines.filter(l=>l.teamId===equipmentDraft.orgUnitId))
const editDeviceStations=computed(()=>catalog.value.stations.filter(s=>s.lineId===equipmentDraft.lineId))
const teams=computed(()=>organizations.value.filter(o=>o.type==='TEAM'))
const equipmentFilterLines=computed(()=>catalog.value.lines.filter(line=>!equipmentFilter.orgUnitId||line.teamId===equipmentFilter.orgUnitId))
const equipmentFilterStations=computed(()=>catalog.value.stations.filter(station=>!equipmentFilter.lineId||station.lineId===equipmentFilter.lineId).filter(station=>!equipmentFilter.orgUnitId||equipmentFilterLines.value.some(line=>line.id===station.lineId)))
const equipmentFilterNames=computed(()=>Array.from(new Set(equipment.value.filter(item=>!equipmentFilter.orgUnitId||item.orgUnitId===equipmentFilter.orgUnitId).filter(item=>!equipmentFilter.lineId||item.lineId===equipmentFilter.lineId).filter(item=>!equipmentFilter.stationId||item.stationId===equipmentFilter.stationId).filter(item=>!equipmentFilter.status||item.status===equipmentFilter.status).map(item=>item.name))).sort((a,b)=>a.localeCompare(b,'zh-CN')))
const filteredEquipment=computed(()=>equipment.value.filter(item=>(!equipmentFilter.orgUnitId||item.orgUnitId===equipmentFilter.orgUnitId)&&(!equipmentFilter.lineId||item.lineId===equipmentFilter.lineId)&&(!equipmentFilter.stationId||item.stationId===equipmentFilter.stationId)&&(!equipmentFilter.status||item.status===equipmentFilter.status)&&(!equipmentFilter.name||item.name===equipmentFilter.name)))


const businessForm=ref<FormSpec|null>(null),mobileMenu=ref(false),showScheduleEditor=ref(false),scheduleBusy=ref(false)
function setForm(spec:FormSpec){businessForm.value={...spec,draftKey:'ux:web:'+me.value?.userId+':'+spec.path+':'+String(spec.initial?.version??'new')}}
function formSaved(result:any){if(active.value==='schedule'){businessForm.value=null;loadSchedules();return}if(active.value==='tasks'){businessForm.value=null;loadTasks();return}selectedDossier.value=result;businessForm.value=null;loadIncidents(incidentPage.value)}
function routeRead(){const q=new URLSearchParams(location.hash.slice(1));const page=q.get('page') as Page;if(navigation.value.some(n=>n.key===page))active.value=page;else active.value='dashboard';if(/^\d{4}-\d{2}$/.test(q.get('period')||''))period.value=q.get('period')!;for(const key of ['from','to'] as const){if(/^\d{4}-\d{2}-\d{2}$/.test(q.get(key)||''))scheduleFilter[key]=q.get(key)!}refreshActive()}
function routeWrite(){const q=new URLSearchParams({page:active.value,period:period.value,from:scheduleFilter.from,to:scheduleFilter.to});history.replaceState(null,'','#'+q)}
watch([period,()=>scheduleFilter.from,()=>scheduleFilter.to],routeWrite)
onMounted(()=>window.addEventListener('hashchange',routeRead))
onUnmounted(()=>window.removeEventListener('hashchange',routeRead))


const tasks=ref<any[]>([]),taskIncidents=ref<any[]>([]),taskFilter=ref('all'),inbox=ref<any[]>([]),inboxMore=ref(false),unreadOnly=ref(false),inboxBusy=ref(false)
const shownTasks=computed(()=>taskFilter.value==='overdue'?[]:tasks.value)
const shownIncidents=computed(()=>taskFilter.value==='overdue'?taskIncidents.value.filter(i=>i.statements?.some((s:any)=>s.status==='OVERDUE')):taskIncidents.value)
async function loadTasks(){try{const [p,i]=await Promise.all([apiGet<any[]>('/performance-cases/pending'),apiGet<any[]>('/incidents/review-queue')]);tasks.value=p;taskIncidents.value=i}catch(e){showError(e,'待办读取失败')}}
function goTasks(filter='all'){taskFilter.value=filter;switchPage('tasks')}
let inboxSequence=0
async function loadMessages(append=false){if(append&&inboxBusy.value)return;const sequence=++inboxSequence,onlyUnread=unreadOnly.value;inboxBusy.value=true;if(!append){inbox.value=[];inboxMore.value=false}try{const result=await apiGet<any>('/notifications?limit=50&offset='+(append?inbox.value.length:0)+'&unreadOnly='+onlyUnread);if(sequence!==inboxSequence)return;inbox.value=append?[...inbox.value,...result.items.filter((row:any)=>!inbox.value.some(item=>item.id===row.id))]:result.items;inboxMore.value=result.hasMore}catch(e){if(sequence===inboxSequence)showError(e,'消息读取失败')}finally{if(sequence===inboxSequence)inboxBusy.value=false}}
async function openMessage(item:any){try{if(!item.readAt)await apiPost('/notifications/'+item.id+'/read',{acknowledge:false});if(item.sourceType==='EQUIPMENT_INCIDENT'){switchPage('incidents');await openDossier(item.sourceId)}else if(item.sourceType==='PERFORMANCE_CASE'){const date=await apiGet<string>('/notifications/'+item.id+'/source-date');if(date)period.value=date.slice(0,7);switchPage('performance')}else if(item.sourceType==='SCHEDULE_ASSIGNMENT'){const date=await apiGet<string>('/notifications/'+item.id+'/source-date');if(date){scheduleFilter.from=date;scheduleFilter.to=date}switchPage('schedule')}else await loadMessages()}catch(e){showError(e,'消息打开失败')}}
function reviewCase(item:any,decision:string){const fields:any[]=[];if(decision==='APPROVE'&&isSupervisor.value){fields.push({key:'score',label:'确认分值',type:'number',min:1,required:true},{key:'ruleCode',label:'生效规则',type:'select',required:true})}fields.push(textField('comment',decision==='APPROVE'?'审核意见':'退回／否决原因',decision!=='APPROVE'));setForm({title:label(decision)+' · '+item.targetName,description:item.description,path:'/performance-cases/'+item.id+'/actions',initial:{version:item.version,decision,score:item.suggestedScore||'',ruleCode:'',comment:''},fields,ruleType:decision==='APPROVE'&&isSupervisor.value?(item.caseType==='BONUS'?'BONUS':'PENALTY'):undefined,ruleDate:item.occurredAt?.slice(0,10)})}
function reviewStatement(item:any,decision:string){setForm({title:decision==='APPROVE'?'通过异常说明':'退回异常说明',description:'异常现象：'+(item.phenomenon||'')+'\n处理方法：'+(item.handlingMethod||'')+'\n问题根因：'+(item.rootCause||''),path:'/incidents/statements/'+item.id+'/review',initial:{version:item.version,decision,comment:''},fields:[textField('comment','审核意见',decision==='RETURN')]})}

const liveConnected=ref(false)
let stopScoreWatch:(()=>void)|undefined
function connectScoreWatch(){
 stopScoreWatch?.();stopScoreWatch=undefined;liveConnected.value=false
 if(typeof document==='undefined'||document.visibilityState!=='visible'||!me.value||me.value.passwordChangeRequired||!['dashboard','performance','settlement'].includes(active.value))return
 stopScoreWatch=startScoreWatch(since=>{const controller=new AbortController();return {promise:apiGet<{revision:string}>('/score-changes?since='+encodeURIComponent(since),controller.signal),cancel:()=>controller.abort()}},async()=>{
   if(active.value==='dashboard'){workbench.value=await apiGet('/workbench');await dailyBoard.value?.refresh()}
   else await loadPerformance()
   updatedAt.value=new Date().toLocaleTimeString()
 },connected=>{liveConnected.value=connected})
}
watch([()=>me.value?.userId,()=>me.value?.passwordChangeRequired,active],connectScoreWatch,{flush:'post'})
let refreshTimer:ReturnType<typeof setInterval>|undefined
const updatedAt=ref('')
let refreshingActive=false
async function refreshActive(){if(!me.value||me.value.passwordChangeRequired||refreshingActive)return;refreshingActive=true;try{if(active.value==='performance'||active.value==='settlement')await loadPerformance();else if(active.value==='schedule')await loadSchedules(true);else if(active.value==='incidents')await loadIncidents();else if(active.value==='tasks')await loadTasks();else if(active.value==='messages')await loadMessages();else if(active.value==='dashboard')workbench.value=await apiGet('/workbench');updatedAt.value=new Date().toLocaleTimeString()}catch(e){showError(e,'刷新失败，请重试')}finally{refreshingActive=false}}
onMounted(async()=>{document.addEventListener('visibilitychange',connectScoreWatch);if(localStorage.getItem('access_token'))await loadContext();refreshTimer=setInterval(()=>{if(document.visibilityState==='visible'&&!['dashboard','performance','settlement','messages','incidents'].includes(active.value))refreshActive()},15000)})
onUnmounted(()=>{stopScoreWatch?.();document.removeEventListener('visibilitychange',connectScoreWatch);if(refreshTimer)clearInterval(refreshTimer)})
async function login(){error.value='';loading.value=true;try{const token=await apiPost<Token>('/auth/account/login',{...loginForm,clientType:'WEB'});localStorage.setItem('access_token',token.accessToken);passwordForm.currentPassword=loginForm.password;loginForm.password='';await loadContext()}catch(e){showError(e,'登录失败')}finally{loading.value=false}}
async function loadContext(){loading.value=true;error.value='';try{const current=await apiGet<CurrentUser>('/me');me.value=current;if(current.passwordChangeRequired)return;[workbench.value,catalog.value,directory.value]=await Promise.all([apiGet<Workbench>('/workbench'),apiGet<Catalog>('/catalog'),apiGet<Person[]>('/directory/people')]);routeRead();await Promise.all([loadPerformance(),loadSchedules(),loadIncidents(),loadAdministration()])}catch(e){showError(e,'系统数据加载失败')}finally{loading.value=false}}
async function changePassword(){if(passwordForm.newPassword!==passwordForm.confirmPassword){error.value='两次输入的新密码不一致';return}if(!/^(?=.*[A-Za-z])(?=.*\d).{8,128}$/.test(passwordForm.newPassword)){error.value='新密码至少8位，并且必须同时包含字母和数字';return}try{const token=await apiPost<Token>('/auth/account/password',{currentPassword:passwordForm.currentPassword,newPassword:passwordForm.newPassword});localStorage.setItem('access_token',token.accessToken);Object.assign(passwordForm,{currentPassword:'',newPassword:'',confirmPassword:''});await loadContext()}catch(e){showError(e,'密码修改失败')}}
async function logout(){try{await apiPost('/auth/logout',{})}catch{}localStorage.removeItem('access_token');me.value=null;workbench.value=null;active.value='dashboard'}
function showError(e:unknown,fallback:string){error.value=e instanceof Error?e.message:fallback}
function switchPage(page:Page){active.value=page;mobileMenu.value=false;error.value='';location.hash=new URLSearchParams({page,period:period.value,from:scheduleFilter.from,to:scheduleFilter.to}).toString();refreshActive()}
function changeEquipmentTeamFilter(){equipmentFilter.lineId='';equipmentFilter.stationId='';equipmentFilter.name=''}
function changeEquipmentLineFilter(){equipmentFilter.stationId='';equipmentFilter.name=''}
function changeEquipmentStationFilter(){equipmentFilter.name=''}
function resetEquipmentFilter(){Object.assign(equipmentFilter,{orgUnitId:'',lineId:'',stationId:'',status:'',name:''})}

let performanceSequence=0
async function loadPerformance(){
 if(!me.value)return
 const sequence=++performanceSequence,month=period.value,actor=me.value.userId
 const [records,mine,overview,runs,corrections]=await Promise.all([
  isAssistant.value||isSupervisor.value||isManager.value?apiGet<PerformanceRecord[]>('/performance-cases/records?period='+month):null,
  isScored.value?apiGet<Personal>('/performance/me?period='+month):null,
  isSupervisor.value||isManager.value?apiGet<{people:PersonScore[];gradeCounts:Record<string,number>}>('/performance/overview?period='+month):null,
  isSupervisor.value||isManager.value?apiGet<Settlement[]>('/settlements?period='+month):null,
  isSupervisor.value||isManager.value?apiGet<SettlementCorrection[]>('/settlement-corrections?period='+month):null
 ])
 if(sequence!==performanceSequence||period.value!==month||me.value?.userId!==actor)return
 if(records)performanceRecords.value=records
 if(mine)personal.value=mine
 if(overview){scores.value=overview.people;gradeCounts.value=overview.gradeCounts}
 if(runs)settlements.value=runs
 if(corrections)settlementCorrections.value=corrections
}
async function loadSchedules(background=false){if(!me.value||!(isAssistant.value||isSupervisor.value||isManager.value))return;const version=++scheduleLoadVersion;if(!background){schedules.value=[];schedulePage.value=1;}scheduleLoading.value=false;if(!scheduleFilter.from||!scheduleFilter.to||scheduleFilter.from>scheduleFilter.to){error.value='请选择有效的排班日期范围，结束日期不能早于开始日期';return}scheduleLoading.value=true;try{const rows=await apiGet<Schedule[]>(`/schedules?from=${scheduleFilter.from}&to=${scheduleFilter.to}`);if(version===scheduleLoadVersion){schedules.value=rows;schedulePage.value=Math.min(schedulePage.value,schedulePageCount.value)}}catch(e){if(version===scheduleLoadVersion)showError(e,'排班查询失败')}finally{if(version===scheduleLoadVersion)scheduleLoading.value=false}}
async function createSchedule(){if(scheduleBusy.value)return;if(!scheduleForm.userIds.length||!scheduleForm.stationIds.length){error.value='请选择人员和站位';return}if(scheduleForm.userIds.length>2){error.value='同一站位同一班次最多安排2人，请分批安排';return}if(!scheduleForm.from||!scheduleForm.to||scheduleForm.from>scheduleForm.to){error.value='请检查起止日期';return}const people=eligiblePeople.value.filter(p=>scheduleForm.userIds.includes(p.id));const stations=scheduleStations.value.filter(p=>scheduleForm.stationIds.includes(p.id));if(people.length!==scheduleForm.userIds.length||stations.length!==scheduleForm.stationIds.length){error.value='人员或站位已变化，请重新选择';return}const days=Math.round((Date.parse(scheduleForm.to)-Date.parse(scheduleForm.from))/86400000)+1;const payload={...scheduleForm,userIds:[...scheduleForm.userIds],stationIds:[...scheduleForm.stationIds],reason:scheduleForm.reason||null};if(!confirm((payload.publish?'发布排班并通知':'保存排班草稿')+'\n'+payload.from+' 至 '+payload.to+' · '+(payload.shiftCode==='NIGHT'?'夜班':'白班')+'\n人员：'+people.map(p=>p.name+'（'+p.employeeNo+'）').join('、')+'\n站位：'+stations.map(p=>p.name).join('、')+'\n每位人员将安排到所有所选站位，共 '+days*people.length*stations.length+' 条安排。'+(payload.publish?'将通知所选 '+people.length+' 位人员。':'不会通知人员。')+'现有排班冲突由服务端校验，冲突时请调整后重试。'))return;scheduleBusy.value=true;try{await apiPost('/schedules/batch',payload);scheduleFilter.from=payload.from;scheduleFilter.to=payload.to;await loadSchedules();scheduleForm.userIds=[];scheduleForm.stationIds=[];showScheduleEditor.value=false}catch(e){showError(e,'排班保存失败')}finally{scheduleBusy.value=false}}
async function cancelSchedule(item:Schedule){setForm({title:'取消／纠正排班',description:`${item.businessDate} · ${item.displayName} · ${item.lineName} / ${item.stationName}\n提交后该排班将被取消，请核对人员与站位。`,path:`/schedules/${item.id}/cancel`,initial:{version:item.version,reason:''},fields:[{key:'reason',label:'取消／纠正原因',type:'textarea',required:true,max:1000}]})}

async function loadIncidents(page=0){if(!me.value||!(isAssistant.value||isSupervisor.value||isManager.value))return;const sequence=++incidentSequence;incidentLoading.value=false;incidentError.value='';if(incidentFilter.from&&incidentFilter.to&&incidentFilter.from>incidentFilter.to){incidentError.value='结束日期不能早于开始日期';return}const params=incidentParams(),snapshot=params.toString();params.set('page',String(typeof page==='number'?page:0));params.set('size','20');incidentLoading.value=true;try{const result=await apiGet<{items:Incident[];total:number;page:number;open:number;archived:number;voided:number}>('/incidents/search?'+params);if(sequence!==incidentSequence)return;incidents.value=result.items;incidentTotal.value=result.total;incidentPage.value=result.page;incidentSummary.value={open:result.open,archived:result.archived,voided:result.voided};incidentApplied.value=snapshot}catch(e){if(sequence===incidentSequence)incidentError.value=e instanceof Error?e.message:'异常查询失败，请重试'}finally{if(sequence===incidentSequence)incidentLoading.value=false}}
async function openDossier(id:string){const sequence=++dossierSequence;selectedDossier.value=null;dossierLoading.value=true;try{const result=await apiGet<Dossier>(`/incidents/${id}/dossier`);if(sequence===dossierSequence)selectedDossier.value=result}catch(e){if(sequence===dossierSequence)showError(e,'档案加载失败')}finally{if(sequence===dossierSequence)dossierLoading.value=false}}
async function editDossierMetadata(){const d=selectedDossier.value;if(!d)return;setForm({title:'修改异常摘要',path:'/incidents/'+d.id+'/dossier/metadata',method:'PUT',initial:{version:d.version,severity:d.severity,categoryCode:d.categoryCode,impactLevel:d.impactLevel,downtimeMinutes:d.downtimeMinutes,impactDescription:d.impactDescription||'',performanceRequired:d.performanceRequired},fields:[{key:'categoryCode',label:'异常分类',required:true},choice('severity','严重程度',['GENERAL','IMPORTANT','MAJOR']),choice('impactLevel','影响等级',['LOW','MEDIUM','HIGH']),{key:'downtimeMinutes',label:'停机分钟数',type:'number',required:true,min:0},textField('impactDescription','影响说明',false)]})}
async function submitInvestigation(){const d=selectedDossier.value;if(!d)return;setForm({title:'填写调查结论',path:'/incidents/'+d.id+'/dossier/investigation',method:'PUT',initial:{version:d.investigation?.version??null,mode:'SIMPLE',directCause:d.investigation?.directCause||'',rootCause:d.investigation?.rootCause||'',rootCauseCategory:d.investigation?.rootCauseCategory||'设备故障',conclusion:d.investigation?.conclusion||'',fiveWhys:null},fields:[textField('directCause','直接原因'),textField('rootCause','根本原因'),{key:'rootCauseCategory',label:'根因分类',required:true},textField('conclusion','调查结论')]})}
async function confirmInvestigation(){const d=selectedDossier.value;if(!d?.investigation)return;try{selectedDossier.value=await apiPost(`/incidents/${d.id}/dossier/investigation/confirm`,{version:d.investigation.version})}catch(e){showError(e,'调查确认失败')}}
async function addCorrectiveAction(){const d=selectedDossier.value;if(!d)return;setForm({title:'新增整改措施',path:'/incidents/'+d.id+'/dossier/actions',initial:{actionType:'CORRECTIVE',ownerId:'',content:'',dueAt:chinaInput(new Date(Date.now()+3*86400000))},fields:[{key:'ownerId',label:'整改责任人',type:'select',required:true,options:peopleOptions(directory.value)},textField('content','整改措施'),{key:'dueAt',label:'截止时间（北京时间）',type:'datetime-local',required:true}]})}
async function acceptCorrectiveAction(action:Dossier['actions'][number],decision:'ACCEPTED'|'RETURNED'){setForm({title:decision==='RETURNED'?'退回整改':'整改验收',path:'/incidents/dossier/actions/'+action.id+'/accept',initial:{version:action.version,decision,comment:''},fields:[textField('comment',decision==='RETURNED'?'退回原因':'验收意见',decision==='RETURNED')]})}
async function archiveDossier(){const d=selectedDossier.value;if(!d||!confirm(`确认归档 ${d.incidentNo}？归档后仅能追加或更正。`))return;try{selectedDossier.value=await apiPost(`/incidents/${d.id}/dossier/archive`,{version:d.version});await loadIncidents()}catch(e){showError(e,'档案归档失败')}}
async function loadAdministration(){if(!me.value)return;if(isManager.value||isAdmin.value)organizations.value=await apiGet<Org[]>('/admin/organizations');if(isAdmin.value){[users.value,equipment.value,audit.value]=await Promise.all([apiGet<UserItem[]>('/admin/users'),apiGet<Equipment[]>('/admin/equipment'),apiGet<AuditItem[]>('/admin/audit-logs?limit=200')]);catalog.value=await apiGet<Catalog>('/admin/catalog')}if(isManager.value||isAdmin.value)ruleVersions.value=await apiGet<RuleVersion[]>('/admin/rule-versions')}
async function download(path:string,name:string){try{const blob=await apiDownload(path),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}catch(e){showError(e,'导出失败')}}
function exportPerformance(){download(`/exports/performance?period=${period.value}`,`绩效统计_${period.value}.xlsx`)}
function exportSchedules(){download(`/exports/schedules?from=${scheduleFilter.from}&to=${scheduleFilter.to}`,`责任排班_${scheduleFilter.from}_${scheduleFilter.to}.xlsx`)}
async function exportIncidents(){if(incidentExporting.value||incidentLoading.value||incidentChanged.value||!incidentApplied.value||incidentError.value)return;incidentExporting.value=true;try{await download(`/exports/incidents?${incidentApplied.value}`,`设备异常_${incidentTotal.value}条.xlsx`)}finally{incidentExporting.value=false}}
function exportIncidentMonthly(){const p=new URLSearchParams();if(incidentFilter.from)p.set('from',incidentFilter.from);if(incidentFilter.to)p.set('to',incidentFilter.to);download(`/exports/incidents/monthly?${p}`,`异常月度汇总.xlsx`)}

async function createUser(){try{await apiPost('/admin/users',userForm);Object.assign(userForm,{employeeNo:'',displayName:'',orgUnitId:''});users.value=await apiGet('/admin/users')}catch(e){showError(e,'人员创建失败')}}
async function importUsers(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{const result=await apiUpload<{inserted:number;updated:number}>('/admin/users/import',file);users.value=await apiGet('/admin/users');alert(`导入完成：新增 ${result.inserted}，更新 ${result.updated}`)}catch(reason){showError(reason,'人员导入失败')}finally{input.value=''}}
async function importEquipment(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{const result=await apiUpload<{inserted:number;updated:number;linesCreated:number;stationsCreated:number}>('/admin/equipment/import',file);[equipment.value,catalog.value]=await Promise.all([apiGet<Equipment[]>('/admin/equipment'),apiGet<Catalog>('/admin/catalog')]);alert(`设备台账导入完成：新增设备 ${result.inserted}，更新设备 ${result.updated}，自动创建线体 ${result.linesCreated}，自动创建站位 ${result.stationsCreated}`)}catch(reason){showError(reason,'设备台账导入失败')}finally{input.value=''}}
async function toggleUser(user:UserItem){try{await apiPost(`/admin/users/${user.id}`,{displayName:user.displayName,orgUnitId:user.orgUnitId,status:user.status==='ACTIVE'?'DISABLED':'ACTIVE'},'PUT');users.value=await apiGet('/admin/users')}catch(e){showError(e,'状态修改失败')}}
async function resetCredential(user:UserItem){if(!confirm(`将 ${user.displayName} 的密码重置为工号，并强制下次登录改密？`))return;try{await apiPost(`/admin/users/${user.id}/credential/reset`,{});users.value=await apiGet('/admin/users')}catch(e){showError(e,'密码重置失败')}}
async function unlock(user:UserItem){try{await apiPost(`/admin/users/${user.id}/unlock`,{});users.value=await apiGet('/admin/users')}catch(e){showError(e,'解锁失败')}}
async function unbind(user:UserItem){if(!confirm(`确认解绑 ${user.displayName} 的微信并注销全部会话？`))return;try{await apiDelete(`/admin/users/${user.id}/wechat-binding`);users.value=await apiGet('/admin/users')}catch(e){showError(e,'解绑失败')}}
async function changeRole(user:UserItem){const next=roleDraft[user.id];if(!next)return;try{for(const role of user.roles)await apiDelete('/admin/role-bindings',{userId:user.id,roleCode:role,scopeId:user.orgUnitId});if(next!=='NONE')await apiPost('/admin/role-bindings',{userId:user.id,roleCode:next,scopeId:user.orgUnitId});users.value=await apiGet('/admin/users')}catch(e){showError(e,'角色修改失败')}}

async function createLine(){try{await apiPost('/admin/catalog/lines',lineForm);catalog.value=await apiGet('/admin/catalog');Object.assign(lineForm,{teamId:'',code:'',name:''})}catch(e){showError(e,'线体创建失败')}}
async function createStation(){try{await apiPost('/admin/catalog/stations',stationForm);catalog.value=await apiGet('/admin/catalog');Object.assign(stationForm,{lineId:'',code:'',name:''})}catch(e){showError(e,'站位创建失败')}}
function editLine(item:Line){editingLineId.value=item.id;Object.assign(lineDraft,{code:item.code,name:item.name,status:item.status,version:item.version})}
async function saveLine(item:Line){try{await apiPost(`/admin/catalog/lines/${item.id}`,lineDraft,'PUT');catalog.value=await apiGet('/admin/catalog');editingLineId.value=''}catch(e){showError(e,'线体修改失败')}}
function editStation(item:Station){editingStationId.value=item.id;Object.assign(stationDraft,{code:item.code,name:item.name,status:item.status,version:item.version})}
async function saveStation(item:Station){try{await apiPost(`/admin/catalog/stations/${item.id}`,stationDraft,'PUT');catalog.value=await apiGet('/admin/catalog');editingStationId.value=''}catch(e){showError(e,'站位修改失败')}}
async function createEquipment(){try{await apiPost('/admin/equipment',equipmentForm);equipment.value=await apiGet('/admin/equipment');Object.assign(equipmentForm,{code:'',name:'',category:'',orgUnitId:'',lineId:'',stationId:''})}catch(e){showError(e,'设备创建失败')}}
function editEquipment(item:Equipment){editingEquipmentId.value=item.id;Object.assign(equipmentDraft,{code:item.code,name:item.name,category:item.category,orgUnitId:item.orgUnitId,lineId:item.lineId,stationId:item.stationId,status:item.status,version:item.version})}
async function saveEquipment(item:Equipment){try{await apiPost(`/admin/equipment/${item.id}`,equipmentDraft,'PUT');equipment.value=await apiGet('/admin/equipment');editingEquipmentId.value=''}catch(e){showError(e,'设备信息修改失败')}}
async function toggleEquipment(item:Equipment){try{await apiPost(`/admin/equipment/${item.id}`,{...item,status:item.status==='ACTIVE'?'DISABLED':'ACTIVE'},'PUT');equipment.value=await apiGet('/admin/equipment')}catch(e){showError(e,'设备状态修改失败')}}
async function createShift(){try{await apiPost('/admin/catalog/shifts',shiftForm);catalog.value=await apiGet('/admin/catalog')}catch(e){showError(e,'班次版本保存失败')}}
async function saveCalendar(){try{await apiPost(`/admin/calendar/${calendarForm.date}`,{dayType:calendarForm.dayType,name:calendarForm.name},'PUT');alert('日历配置已保存')}catch(e){showError(e,'日历保存失败')}}

async function createVersion(){try{const created=await apiPost<RuleVersion>('/admin/rule-versions',{version:versionName.value});versionName.value='';ruleVersions.value=await apiGet('/admin/rule-versions');await selectRuleVersion(created)}catch(e){showError(e,'版本创建失败')}}
async function selectRuleVersion(version:RuleVersion){selectedVersion.value=version;rules.value=await apiGet(`/admin/rule-versions/${version.id}/rules`)}
async function addRule(){if(!selectedVersion.value)return;try{await apiPost(`/admin/rule-versions/${selectedVersion.value.id}/rules`,{code:ruleForm.code.toUpperCase(),title:ruleForm.title,type:ruleForm.type,score:ruleForm.type==='D_GRADE'?null:Number(ruleForm.score),capPolicy:{monthlyCap:Number(ruleForm.monthlyCap)},evidenceSchema:{attachmentRequired:false,maxImages:9},approvalFlow:{firstNode:ruleForm.type==='BONUS'?'ASSISTANT_ENGINEER':'SUPERVISOR'},effectiveFrom:ruleForm.effectiveFrom,effectiveTo:ruleForm.effectiveTo||null});rules.value=await apiGet(`/admin/rule-versions/${selectedVersion.value.id}/rules`);ruleForm.code='';ruleForm.title=''}catch(e){showError(e,'规则添加失败')}}
async function publishVersion(version:RuleVersion){if(!confirm(`确认由系统管理员发布规则版本 ${version.version}？历史规则将保持不变。`))return;try{await apiPost(`/admin/rule-versions/${version.id}/publish`,{});ruleVersions.value=await apiGet('/admin/rule-versions')}catch(e){showError(e,'规则发布失败')}}

function dateOffset(days:number){const d=new Date();d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
</script>

<template>
<div v-if="!me" class="login-shell"><div class="login-visual"><div class="logo-box">测</div><h1>测试工程部积分绩效</h1><p>责任到人，过程留痕，数据可追溯</p><div class="visual-grid"><span>责任排班</span><span>绩效闭环</span><span>异常归档</span></div></div><form class="login-card" @submit.prevent="login"><div><small>TEST ENGINEERING</small><h2>欢迎登录</h2><p>使用工号及密码进入管理后台</p></div><label>工号<input v-model.trim="loginForm.username" autocomplete="username" maxlength="64" placeholder="请输入账号或工号" required></label><label>密码<input v-model="loginForm.password" type="password" autocomplete="current-password" maxlength="128" placeholder="首次登录密码为本人工号" required></label><p v-if="error" class="error-box">{{ error }}</p><button class="primary-button" :disabled="loading">{{ loading?'正在登录…':'登录系统' }}</button><small class="security-tip">连续输错5次将锁定30分钟</small></form></div>
  <div v-else-if="me.passwordChangeRequired" class="login-shell"><div class="login-visual"><div class="logo-box">密</div><h1>保护账号安全</h1><p>首次登录必须修改默认密码</p></div><form class="login-card" @submit.prevent="changePassword"><h2>设置新密码</h2><p>至少8位，并且同时包含字母和数字</p><label>当前密码<input v-model="passwordForm.currentPassword" type="password" required></label><label>新密码<input v-model="passwordForm.newPassword" type="password" minlength="8" required></label><label>确认新密码<input v-model="passwordForm.confirmPassword" type="password" minlength="8" required></label><p v-if="error" class="error-box">{{ error }}</p><button class="primary-button">修改密码并进入</button></form></div>
  <div v-else class="app-shell">
    <aside class="sidebar"><div class="brand"><div class="mini-logo">测</div><div><strong>测试工程部</strong><small>积分绩效管理</small></div></div><button class="mobile-menu" @click="mobileMenu=!mobileMenu" :aria-expanded="mobileMenu">菜单</button><nav :class="{'menu-open':mobileMenu}"><button v-for="item in navigation" :key="item.key" :class="{active:active===item.key}" @click="switchPage(item.key)"><span>{{ item.mark }}</span>{{ item.label }}</button></nav><div class="sidebar-user"><div class="avatar">{{ me.displayName.slice(0,1) }}</div><div><strong>{{ me.displayName }}</strong><small>{{ me.employeeNo }} · {{ roleText }}</small></div><button title="退出" @click="logout">↗</button></div></aside>
    <main class="main"><header class="topbar"><div><small>测试工程部 / {{ pageTitles[active] }}</small><h1>{{ pageTitles[active] }}</h1></div><div class="top-actions"><span class="online-dot"></span><span>{{ error?'数据加载异常':loading?'正在刷新':['dashboard','performance','settlement'].includes(active)?(liveConnected?'自动更新已连接':'自动更新连接中'):'已连接' }}</span><button class="ghost" @click="loadContext();dailyBoard?.refresh()">刷新数据</button></div></header><p v-if="error" class="error-box global-error">{{ error }} <button @click="error=''">×</button></p>

      <section v-if="active==='equipment'" class="equipment-import"><div><strong>一键导入设备台账</strong><small>Excel 列：设备编号、设备名称、设备类别、班组、线体、站位、状态。班组必须已存在；线体或站位不存在时会自动创建。</small></div><label class="upload">选择 Excel 导入<input type="file" accept=".xlsx,.xls" @change="importEquipment"></label></section>
      <section v-if="active==='settlement' && settlementCorrections.length" class="panel correction-panel"><div class="panel-head"><div><h3>封存后更正记录</h3><p>Web 端只读。发起和审批均在小程序完成；达到当前表决条件后会自动生成新的结算批次。</p></div><b>{{ settlementCorrections.length }}</b></div><div class="table-wrap"><table><thead><tr><th>人员</th><th>调整分值</th><th>原因</th><th>发起人</th><th>审批进度</th><th>状态</th></tr></thead><tbody><tr v-for="item in settlementCorrections" :key="item.id"><td><strong>{{ item.displayName }}</strong><small>{{ item.employeeNo }}</small></td><td><span :class="['correction-value',{negative:item.adjustmentScore<0}]">{{ item.adjustmentScore>0?'+':'' }}{{ item.adjustmentScore }}</span></td><td>{{ item.reason }}</td><td>{{ item.requesterName }}</td><td>{{ item.approvals }} / {{ item.requiredApprovals }}</td><td><span class="status warning">{{ correctionLabels[item.status] || item.status }}</span></td></tr></tbody></table></div></section>

      <template v-if="active==='dashboard'"><section class="welcome"><div><small>{{ new Date().toLocaleDateString('zh-CN',{weekday:'long',year:'numeric',month:'long',day:'numeric'}) }}</small><h2>{{ me.displayName }}，欢迎回来</h2><p>这里汇总今天需要关注的排班、绩效和设备异常。</p></div><div class="welcome-mark">TE</div></section><section class="metric-grid"><article role="button" tabindex="0" @click="switchPage('messages')" @keydown.enter="switchPage('messages')"><span>未读消息</span><strong>{{ workbench?.pending.unreadMessages||0 }}</strong><small>站内通知与业务提醒</small></article><article role="button" tabindex="0" @click="switchPage('schedule')" @keydown.enter="switchPage('schedule')"><span>近期排班</span><strong>{{ workbench?.currentSchedules.length||0 }}</strong><small>发布即生效，无需人员确认</small></article><article role="button" tabindex="0" @click="goTasks()" @keydown.enter="goTasks()"><span>待审核事项</span><strong>{{ (workbench?.pending.performanceReviews||0)+(workbench?.pending.incidentReviews||0) }}</strong><small>绩效与异常说明</small></article><article class="danger-metric" role="button" tabindex="0" @click="goTasks('overdue')" @keydown.enter="goTasks('overdue')"><span>逾期异常</span><strong>{{ workbench?.pending.overdueIncidents||0 }}</strong><small>需主管决定扣分或劝诫</small></article></section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3>近期责任排班</h3><p>已发布且接近当前时间的责任安排</p></div><button class="link" @click="switchPage('schedule')">查看全部</button></div><div v-if="!workbench?.currentSchedules.length" class="empty-state">暂无近期排班</div><div v-for="item in workbench?.currentSchedules" :key="item.id" class="compact-row"><span class="date-chip">{{ item.businessDate.slice(5) }}</span><div><strong>{{ item.displayName }} · {{ item.lineName }} / {{ item.stationName }}</strong><small>{{ item.shiftCode==='NIGHT'?'夜班':'白班' }} · 已自动确认</small></div></div></section><section class="panel"><div class="panel-head"><div><h3>近30天高发设备</h3><p>按已归档异常次数排序</p></div></div><div v-if="!workbench?.hotEquipment.length" class="empty-state">暂无高发设备数据</div><div v-for="(item,index) in workbench?.hotEquipment" :key="item.id" class="compact-row"><span class="rank-chip">{{ index+1 }}</span><div><strong>{{ item.name }}</strong><small>{{ item.code }}</small></div><b>{{ item.incidents }} 次</b></div></section></div><DailyDeductionBoard ref="dailyBoard" /></template>

      <template v-if="active==='performance'"><section class="filter-bar"><label>统计月份<input v-model="period" type="month" @change="loadPerformance"></label><button class="secondary" @click="loadPerformance">查询</button><button v-if="isSupervisor||isManager" @click="exportPerformance">导出 Excel</button></section><section v-if="personal" class="personal-score"><div><span>我的月度平均分</span><strong>{{ personal.averageScore }}</strong><small>共 {{ personal.shiftCount }} 个有效班次 · 排名 {{ personal.rank||'-' }}</small></div><div class="score-breakdown"><span>总分<b>{{ personal.total }}</b></span><span>基础<b>{{ personal.base }}</b></span><span>加分<b class="positive">+{{ personal.bonus }}</b></span><span>扣分<b class="negative">-{{ personal.penalty }}</b></span><span v-if="personal.finalGrade">最终等级<b>{{ personal.finalGrade }}</b></span></div></section><template v-if="isSupervisor||isManager"><section class="grade-grid"><article v-for="grade in ['S','A','B1','B2','B3','C','D']" :key="grade"><strong>{{ grade }}</strong><span>{{ gradeCounts[grade]||0 }} 人</span></article></section><section class="panel"><div class="panel-head"><div><h3>人员绩效</h3><p>无有效班次仍保留积分，不参与排名。积分变动后自动更新。最近刷新：{{ updatedAt||'首次加载' }}</p></div></div><div class="table-wrap"><table><thead><tr><th>排名</th><th>工号</th><th>姓名</th><th>班组</th><th>班次</th><th>基础</th><th>加分</th><th>扣分</th><th>总分</th><th>平均分</th><th>预估等级</th></tr></thead><tbody><tr v-for="item in scores" :key="item.userId"><td><span class="table-rank">{{ item.rank||'未参评' }}</span></td><td>{{ item.employeeNo }}</td><td><strong>{{ item.name }}</strong></td><td>{{ item.teamName }}</td><td>{{ item.shiftCount }}</td><td>{{ item.base }}</td><td class="positive">+{{ item.bonus }}</td><td class="negative">-{{ item.penalty }}</td><td>{{ item.total }}</td><td><strong>{{ Number(item.averageScore).toFixed(2) }}</strong></td><td><span class="grade-badge">{{ item.previewGrade||'未参评' }}</span></td></tr></tbody></table></div></section></template><section v-if="isAssistant||isSupervisor||isManager" class="panel"><div class="panel-head"><h3>绩效处理明细</h3><span>当前月份共 {{ filteredRecords.length }} 条</span></div><div class="filter-bar"><label>姓名 / 工号<input v-model="recordFilter.person" placeholder="搜索人员"></label><label>处理状态<select v-model="recordFilter.status"><option value="">全部状态</option><option v-for="(name,code) in recordStatuses" :key="code" :value="code">{{ name }}</option></select></label></div><div class="table-wrap"><table><thead><tr><th>发生时间</th><th>姓名 / 工号</th><th>类型</th><th>原因 / 规则</th><th>建议 / 核定</th><th>实际生效分值</th><th>状态</th><th>发起人</th></tr></thead><tbody><tr v-for="r in filteredRecords" :key="r.id"><td>{{ localTime(r.occurredAt) }}</td><td>{{ r.targetName }} / {{ r.employeeNo }}</td><td>{{ recordTypes[r.caseType]||r.caseType }}</td><td>{{ r.description }}<small>{{ r.ruleCode }}</small></td><td>{{ r.suggestedScore??'-' }} / {{ r.approvedScore??'-' }}</td><td>{{ r.effectiveScore==null?'-':(r.caseType.includes('DEDUCTION')?'-':'+')+r.effectiveScore }}</td><td>{{ recordStatuses[r.status]||r.status }}</td><td>{{ r.initiatorName }}</td></tr></tbody></table><p v-if="!filteredRecords.length">当前条件下没有绩效记录</p></div></section></template>

      <template v-if="active==='schedule'"><section class="filter-bar"><label>开始<input v-model="scheduleFilter.from" type="date"></label><label>结束<input v-model="scheduleFilter.to" type="date"></label><button :disabled="scheduleLoading" @click="resetScheduleDetails();loadSchedules()">{{ scheduleLoading?'查询中…':'查询日期范围' }}</button><button class="secondary" @click="scheduleToday">今天</button><button class="secondary" @click="exportSchedules" title="导出所选起止日期内全部排班，不应用下方明细筛选">导出日期范围全部 Excel</button></section><button v-if="isAssistant||isSupervisor" class="secondary" @click="showScheduleEditor=!showScheduleEditor">{{showScheduleEditor?'收起新增表单':'＋ 新增排班'}}</button><section v-if="(isAssistant||isSupervisor)&&showScheduleEditor" class="panel"><div class="panel-head"><div><h3>批量安排责任排班</h3><p>同一班次同一站位最多2人；助理工程师仅能安排自己及本班组技术员。</p></div></div><form class="schedule-form" @submit.prevent="createSchedule"><label>开始日期<input v-model="scheduleForm.from" type="date" required></label><label>结束日期<input v-model="scheduleForm.to" type="date" required></label><label>班次<select v-model="scheduleForm.shiftCode"><option v-for="item in catalog.shifts" :key="item.id" :value="item.code">{{ item.name }} {{ item.startsAt }}–{{ item.endsAt }}</option></select></label><label>线体<select v-model="scheduleForm.lineId" required @change="scheduleForm.stationIds=[]"><option value="" disabled>选择线体</option><option v-for="item in catalog.lines" :key="item.id" :value="item.id">{{ item.teamName }} · {{ item.name }}</option></select></label><div class="wide">人员（每个站位最多2人）<SearchSelect v-model="scheduleForm.userIds" :options="peopleOptions(eligiblePeople)" label="人员姓名、工号或班组" multiple :disabled="scheduleBusy"/></div><div class="wide">站位（可多选）<SearchSelect v-model="scheduleForm.stationIds" :options="scheduleStations.map(s=>({value:s.id,label:s.name+' · '+s.code}))" label="站位" multiple :disabled="scheduleBusy"/></div><label class="switch-label"><input v-model="scheduleForm.publish" type="checkbox">直接发布并通知（无需确认）</label><button :disabled="scheduleBusy">{{scheduleBusy?'正在保存…':scheduleForm.publish?'预览并发布排班':'预览并保存草稿'}}</button></form></section><section class="panel"><div class="panel-head"><div><h3>责任排班明细</h3><p>已开始排班仅主管可填写原因后纠正，所有修改均保留版本记录。</p></div><b>筛选结果 {{ filteredSchedules.length }} / {{ schedules.length }} 条</b></div><div class="equipment-filter-bar">
<label>日期<select v-model="scheduleDetailFilter.businessDate"><option value="">范围内全部日期</option><option v-for="date in scheduleDates" :key="date" :value="date">{{ date }}</option></select></label>
<label>班组<select v-model="scheduleDetailFilter.teamId" @change="changeScheduleTeam"><option value="">全部班组</option><option v-for="item in scheduleTeams" :key="item.id" :value="item.id">{{ item.name }}</option></select></label>
<label>线体<select v-model="scheduleDetailFilter.lineId" @change="changeScheduleLine"><option value="">全部线体</option><option v-for="item in scheduleLineOptions" :key="item.id" :value="item.id">{{ item.name }}</option></select></label>
<label>站位<select v-model="scheduleDetailFilter.stationId"><option value="">全部站位</option><option v-for="item in scheduleStationOptions" :key="item.id" :value="item.id">{{ item.name }}</option></select></label>
<label>人员<select v-model="scheduleDetailFilter.userId"><option value="">全部人员</option><option v-for="item in schedulePeople" :key="item.id" :value="item.id">{{ item.name }}</option></select></label>
<label>班次<select v-model="scheduleDetailFilter.shiftCode"><option value="">全部班次</option><option value="DAY">白班</option><option value="NIGHT">夜班</option></select></label>
<label>状态<select v-model="scheduleDetailFilter.status"><option value="">全部状态</option><option value="DRAFT">草稿</option><option value="PUBLISHED">已发布</option><option value="CANCELLED">已取消</option></select></label>

<button class="secondary" @click="resetScheduleDetails">清空明细筛选</button>
</div><p>下拉筛选即时生效，仅筛选已查询日期范围；Excel 导出该日期范围全部记录。</p><div v-if="scheduleLoading" class="empty-state">排班查询中…</div><div v-else-if="!filteredSchedules.length" class="empty-state">没有符合当前筛选条件的排班</div><div class="table-wrap"><table><thead><tr><th>业务日期</th><th>班次</th><th>责任人</th><th>班组</th><th>线体</th><th>站位</th><th>状态</th><th>生效方式</th><th v-if="isAssistant||isSupervisor">操作</th></tr></thead><tbody><tr v-for="item in pagedSchedules" :key="item.id"><td>{{ item.businessDate }}</td><td>{{ item.shiftCode==='NIGHT'?'夜班':'白班' }}</td><td><strong>{{ item.displayName }}</strong><br><small>{{ item.employeeNo }}</small></td><td>{{ item.teamName }}</td><td>{{ item.lineName }}</td><td>{{ item.stationName }}</td><td><span :class="['status',item.status.toLowerCase()]">{{ item.status==='PUBLISHED'?'已发布':item.status==='DRAFT'?'草稿':item.status==='CANCELLED'?'已取消':item.status }}</span></td><td><span class="status">{{ item.status==='PUBLISHED'?'自动确认，无需操作':'不适用' }}</span></td><td v-if="isAssistant||isSupervisor"><button v-if="item.status!=='CANCELLED'" class="table-button danger-text" @click="cancelSchedule(item)">取消/纠正</button></td></tr></tbody></table></div><div class="filter-bar"><button class="secondary" :disabled="schedulePage<=1" @click="schedulePage--">上一页</button><span>第 {{ schedulePage }} / {{ schedulePageCount }} 页 · 每页 20 条</span><button class="secondary" :disabled="schedulePage>=schedulePageCount" @click="schedulePage++">下一页</button></div></section></template>

      <template v-if="active==='incidents'"><section class="filter-bar"><label>状态<select v-model="incidentFilter.status"><option value="ALL">全部状态</option><option value="OPEN">处理中</option><option value="ARCHIVED">已归档</option><option value="VOID">已作废</option></select></label><label>开始<input v-model="incidentFilter.from" type="date"></label><label>结束<input v-model="incidentFilter.to" type="date"></label><label>线体<select v-model="incidentFilter.lineId"><option value="">全部线体</option><option v-for="line in catalog.lines" :key="line.id" :value="line.id">{{ line.name }}</option></select></label><label class="grow">关键词<input v-model.trim="incidentFilter.keyword" placeholder="编号、设备、现象、方法、根因或对策"></label><button :disabled="incidentLoading" @click="loadIncidents()">{{incidentLoading?"查询中…":"查询"}}</button><button class="secondary" @click="resetIncidentFilters">重置</button><button class="secondary" :disabled="incidentLoading||incidentChanged||!!incidentError||!incidentApplied||incidentExporting" @click="exportIncidents">{{incidentExporting?"正在导出…":"导出当前筛选全部记录"}}</button></section><p v-if="incidentChanged" class="workflow-banner">筛选条件已更改，请点击查询；当前列表仍为上次查询结果。</p><p v-if="incidentError" class="error-box" role="alert">{{incidentError}} <button @click="loadIncidents()">重试</button></p><section class="metric-grid"><article><span>当前筛选总数</span><strong>{{incidentTotal}}</strong></article><article><span>处理中</span><strong>{{incidentSummary.open}}</strong></article><article><span>已归档</span><strong>{{incidentSummary.archived}}</strong></article><article><span>已作废</span><strong>{{incidentSummary.voided}}</strong></article></section><p v-if="dossierLoading" role="status">正在打开详情…</p><div v-if="selectedDossier" class="dossier-overlay" @click.self="closeDossier"><section class="panel dossier-panel" role="dialog" aria-modal="true" aria-labelledby="dossier-title" tabindex="-1" @keydown.esc="closeDossier"><h2 id="dossier-title">异常详情</h2><div class="panel-head"><div><h3>{{ selectedDossier.incidentNo }} · 完整档案</h3><p>{{ selectedDossier.categoryCode }} · {{ label(selectedDossier.severity) }} · 停机 {{ selectedDossier.downtimeMinutes }} 分钟</p></div><div class="edit-actions"><button class="secondary" @click="editDossierMetadata">编辑摘要</button><button class="secondary" @click="closeDossier">关闭</button></div></div><div v-if="!selectedDossier.archiveReadiness.ready" class="error-box">归档前还需完成：{{ selectedDossier.archiveReadiness.missingItems.join('；') }}</div><div class="dossier-columns"><div><h4>调查结论</h4><p v-if="selectedDossier.investigation">{{ selectedDossier.investigation.rootCauseCategory }}：{{ selectedDossier.investigation.rootCause }}</p><p v-else>尚未提交调查结论</p><button @click="submitInvestigation">填写/更新调查</button><button v-if="isSupervisor&&selectedDossier.investigation?.status==='SUBMITTED'" @click="confirmInvestigation">确认调查结论</button></div><div><h4>整改与验收</h4><button v-if="isSupervisor" @click="addCorrectiveAction">新增整改措施</button><div v-for="action in selectedDossier.actions" :key="action.id" class="compact-row"><div><strong>{{ action.content }}</strong><small>{{ action.ownerName }} · {{ label(action.status) }} · {{ localTime(action.dueAt) }}</small></div><div v-if="isSupervisor&&action.status==='PENDING_ACCEPTANCE'" class="edit-actions"><button class="table-button" @click="acceptCorrectiveAction(action,'ACCEPTED')">验收通过</button><button class="table-button danger-text" @click="acceptCorrectiveAction(action,'RETURNED')">退回</button></div></div></div></div><div class="timeline"><h4>档案时间线</h4><div v-for="event in selectedDossier.events" :key="event.id" class="compact-row"><span class="date-chip">{{ new Date(event.createdAt).toLocaleDateString() }}</span><div><strong>{{ label(event.eventType) }}</strong><small>{{ event.actorName }} · {{ new Date(event.createdAt).toLocaleString() }}</small></div></div></div><button v-if="isSupervisor&&selectedDossier.archiveReadiness.ready" @click="archiveDossier">正式归档</button></section></div><section class="panel"><div class="panel-head"><div><h3>设备异常</h3><p>按当前条件查询全部状态，点击详情查看说明、调查与整改。</p></div><b>共 {{ incidentTotal }} 条</b></div><div v-if="!incidentLoading&&!incidentError&&!incidents.length" class="empty-state">没有符合条件的异常档案</div><article v-for="item in incidents" :key="item.id" class="incident"><div class="incident-head"><div><small>{{ item.incidentNo }} · {{ item.businessDate }}</small><h4>{{ item.lineName }} / {{ item.stationName }}</h4></div><div class="edit-actions"><span :class="['status',item.status.toLowerCase()]">{{ label(item.status) }}</span><button class="table-button" @click="openDossier(item.id)">查看完整档案</button></div></div><div class="device-tags"><span v-for="device in item.devices" :key="device.id">{{ device.category }} · {{ device.code }} · {{ device.name }}</span></div><details><summary>展开责任人说明</summary><div class="statement-grid"><div v-for="statement in item.statements" :key="statement.id"><h5>{{ statement.responsibleName }} <small>{{ statement.employeeNo }}</small></h5><dl><dt>异常现象</dt><dd>{{ statement.phenomenon }}</dd><dt>处理方法</dt><dd>{{ statement.handlingMethod }}</dd><dt>问题根因</dt><dd>{{ statement.rootCause }}</dd><dt>长期对策</dt><dd>{{ statement.longTermAction||'未填写' }}</dd></dl></div></div></details></article><nav class="incident-pagination" aria-label="异常分页"><button :disabled="incidentLoading||incidentChanged||incidentPage===0" @click="incidentPageChange(-1)">上一页</button><span>第 {{incidentPage+1}} / {{Math.max(1,Math.ceil(incidentTotal/20))}} 页 · 共 {{incidentTotal}} 条</span><button :disabled="incidentLoading||incidentChanged||(incidentPage+1)*20>=incidentTotal" @click="incidentPageChange(1)">下一页</button></nav></section></template>

      <template v-if="active==='settlement'"><section class="filter-bar"><label>结算月份<input v-model="period" type="month" @change="loadPerformance"></label><button @click="loadPerformance">查询</button></section><section class="panel"><div class="panel-head"><div><h3>月度封存记录</h3><p>Web 端只读展示；同分边界、D级认定和月度确认均按当前审批配置在小程序完成。</p></div></div><div v-if="!settlements.length" class="empty-state">该月尚未生成预结算</div><template v-for="run in settlements" :key="run.runId"><div class="settlement-summary"><div><strong>{{ run.version }}</strong><small>{{ run.status }}</small></div><span>边界待定 {{ run.manualPending }}</span><span>{{ run.status==='PUBLISHED'?'审批已完成':'审批进行中' }}</span></div><div class="table-wrap"><table><thead><tr><th>排名</th><th>工号</th><th>姓名</th><th>有效班次</th><th>总分</th><th>平均分</th><th>建议等级</th><th>最终等级</th><th>边界状态</th></tr></thead><tbody><tr v-for="item in run.candidates" :key="item.userId"><td>{{ item.rank }}</td><td>{{ item.employeeNo }}</td><td><strong>{{ item.displayName }}</strong></td><td>{{ item.shiftCount }}</td><td>{{ item.total }}</td><td><strong>{{ Number(item.averageScore).toFixed(2) }}</strong></td><td>{{ item.proposedGrade }}</td><td><span class="grade-badge">{{ item.finalGrade }}</span></td><td>{{ item.manualRequired?'待表决':'已确定' }}</td></tr></tbody></table></div></template></section></template>

      <template v-if="active==='organization'"><section v-if="!isAdmin" class="panel"><div class="panel-head"><div><h3>测试工程部人员组织</h3><p>部长为只读查看；人员配置由系统管理员在独立管理入口维护。</p></div></div><div class="table-wrap"><table><thead><tr><th>工号</th><th>姓名</th><th>班组</th><th>角色</th></tr></thead><tbody><tr v-for="item in directory" :key="item.id"><td>{{ item.employeeNo }}</td><td><strong>{{ item.name }}</strong></td><td>{{ item.teamName }}</td><td>{{ item.roles.map(r=>roleNames[r]||r).join('、')||'无业务权限' }}</td></tr></tbody></table></div></section><template v-else><section class="panel"><div class="panel-head"><div><h3>正式人员账号</h3><p>可查看技术员、助理工程师是否开启微信服务通知及剩余可通知次数。</p></div><label class="upload">导入 Excel / CSV<input type="file" accept=".xlsx,.xls,.csv" @change="importUsers"></label></div><form class="inline-form" @submit.prevent="createUser"><input v-model.trim="userForm.employeeNo" placeholder="工号" required><input v-model.trim="userForm.displayName" placeholder="姓名" required><select v-model="userForm.orgUnitId" required><option value="" disabled>所属组织</option><option v-for="org in organizations" :key="org.id" :value="org.id">{{ org.name }}</option></select><button>新增人员</button></form><div class="table-wrap"><table><thead><tr><th>工号</th><th>姓名</th><th>组织</th><th>业务角色</th><th>状态</th><th>微信绑定</th><th>微信通知权限</th><th>密码</th><th>操作</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td>{{ user.employeeNo }}</td><td><strong>{{ user.displayName }}</strong><span v-if="user.administrator" class="admin-badge">管理员</span></td><td>{{ user.orgName }}</td><td><div class="role-editor"><select v-model="roleDraft[user.id]"><option value="" disabled>{{ user.roles.map(r=>roleNames[r]||r).join('、')||'无业务权限' }}</option><option value="TECHNICIAN">技术员</option><option value="ASSISTANT_ENGINEER">助理工程师</option><option value="SUPERVISOR">主管</option><option value="DEPARTMENT_MANAGER">部长</option><option value="NONE">无业务权限</option></select><button class="table-button" @click="changeRole(user)">应用</button></div></td><td><span :class="['status',user.status.toLowerCase()]">{{ user.status==='ACTIVE'?'启用':'停用' }}</span></td><td>{{ user.wechatBound?'已绑定':'未绑定' }}</td><td><template v-if="isWechatNotificationTarget(user)"><span :class="['status',wechatNotificationClass(user)]">{{ wechatNotificationNames[user.wechatNotificationStatus]||user.wechatNotificationStatus }}</span><small v-if="user.wechatNotificationStatus==='ACCEPTED'"> 剩余 {{ user.wechatNotificationCredits }} 次</small><small v-if="user.wechatNotificationUpdatedAt"><br>{{ new Date(user.wechatNotificationUpdatedAt).toLocaleString() }}</small></template><span v-else>-</span></td><td><span v-if="user.lockedUntil" class="status warning">已锁定</span><span v-else-if="user.passwordChangeRequired" class="status warning">待改密</span><span v-else class="status active">正常</span></td><td class="actions"><button class="table-button" @click="resetCredential(user)">重置密码</button><button v-if="user.lockedUntil" class="table-button" @click="unlock(user)">解锁</button><button v-if="user.wechatBound" class="table-button" @click="unbind(user)">解绑微信</button><button class="table-button danger-text" @click="toggleUser(user)">{{ user.status==='ACTIVE'?'停用':'启用' }}</button></td></tr></tbody></table></div></section></template></template>

      <template v-if="active==='equipment'">
        <div class="catalog-grid">
          <section class="panel"><div class="panel-head"><div><h3>线体</h3><p>可修改编号、名称和状态</p></div><b>{{ catalog.lines.length }}</b></div><form class="stack-form" @submit.prevent="createLine"><select v-model="lineForm.teamId" required><option value="" disabled>所属班组</option><option v-for="team in teams" :key="team.id" :value="team.id">{{ team.name }}</option></select><div><input v-model.trim="lineForm.code" placeholder="线体编号" required><input v-model.trim="lineForm.name" placeholder="线体名称" required></div><button>新增线体</button></form><div class="catalog-list"><div v-for="item in catalog.lines" :key="item.id" class="catalog-item"><template v-if="editingLineId===item.id"><input v-model.trim="lineDraft.code" aria-label="线体编号"><input v-model.trim="lineDraft.name" aria-label="线体名称"><small>{{ item.teamName }}</small><select v-model="lineDraft.status"><option value="ACTIVE">启用</option><option value="DISABLED">停用</option></select><div class="edit-actions"><button class="table-button" @click="saveLine(item)">保存</button><button class="table-button muted" @click="editingLineId=''">取消</button></div></template><template v-else><span>{{ item.code }}</span><strong>{{ item.name }}</strong><small>{{ item.teamName }}</small><span :class="['status',item.status.toLowerCase()]">{{ item.status==='ACTIVE'?'启用':'停用' }}</span><button class="table-button" @click="editLine(item)">修改</button></template></div></div></section>
          <section class="panel"><div class="panel-head"><div><h3>站位</h3><p>可修改编号、名称和状态</p></div><b>{{ catalog.stations.length }}</b></div><form class="stack-form" @submit.prevent="createStation"><select v-model="stationForm.lineId" required><option value="" disabled>所属线体</option><option v-for="line in catalog.lines" :key="line.id" :value="line.id">{{ line.name }}</option></select><div><input v-model.trim="stationForm.code" placeholder="站位编号" required><input v-model.trim="stationForm.name" placeholder="站位名称" required></div><button>新增站位</button></form><div class="catalog-list"><div v-for="item in catalog.stations" :key="item.id" class="catalog-item"><template v-if="editingStationId===item.id"><input v-model.trim="stationDraft.code" aria-label="站位编号"><input v-model.trim="stationDraft.name" aria-label="站位名称"><small>{{ item.lineName }}</small><select v-model="stationDraft.status"><option value="ACTIVE">启用</option><option value="DISABLED">停用</option></select><div class="edit-actions"><button class="table-button" @click="saveStation(item)">保存</button><button class="table-button muted" @click="editingStationId=''">取消</button></div></template><template v-else><span>{{ item.code }}</span><strong>{{ item.name }}</strong><small>{{ item.lineName }}</small><span :class="['status',item.status.toLowerCase()]">{{ item.status==='ACTIVE'?'启用':'停用' }}</span><button class="table-button" @click="editStation(item)">修改</button></template></div></div></section>
        </div>
        <section class="panel"><div class="panel-head"><div><h3>设备台账</h3><p>可直接修改设备的班组、线体和站位；停用后小程序自动隐藏，历史异常仍保留。</p></div><button class="secondary export-button" @click="download('/exports/equipment','设备台账.xlsx')">导出 Excel</button></div><div class="equipment-filter-bar"><label>班组<select v-model="equipmentFilter.orgUnitId" @change="changeEquipmentTeamFilter"><option value="">全部班组</option><option v-for="team in teams" :key="team.id" :value="team.id">{{ team.name }}</option></select></label><label>线体<select v-model="equipmentFilter.lineId" @change="changeEquipmentLineFilter"><option value="">全部线体</option><option v-for="line in equipmentFilterLines" :key="line.id" :value="line.id">{{ line.name }}</option></select></label><label>站位<select v-model="equipmentFilter.stationId" @change="changeEquipmentStationFilter"><option value="">全部站位</option><option v-for="station in equipmentFilterStations" :key="station.id" :value="station.id">{{ station.name }}</option></select></label><label>状态<select v-model="equipmentFilter.status" @change="equipmentFilter.name=''"><option value="">全部状态</option><option value="ACTIVE">启用</option><option value="DISABLED">停用</option></select></label><label>名称<select v-model="equipmentFilter.name"><option value="">全部名称</option><option v-for="name in equipmentFilterNames" :key="name" :value="name">{{ name }}</option></select></label><button class="secondary" type="button" @click="resetEquipmentFilter">清空筛选</button><span class="filter-count">显示 {{ filteredEquipment.length }} / {{ equipment.length }} 台</span></div><form class="equipment-form" @submit.prevent="createEquipment"><input v-model.trim="equipmentForm.code" placeholder="设备编号" required><input v-model.trim="equipmentForm.name" placeholder="设备名称" required><input v-model.trim="equipmentForm.category" placeholder="设备类别" required><select v-model="equipmentForm.orgUnitId" required @change="equipmentForm.lineId='';equipmentForm.stationId=''"><option value="" disabled>所属班组</option><option v-for="team in teams" :key="team.id" :value="team.id">{{ team.name }}</option></select><select v-model="equipmentForm.lineId" required @change="equipmentForm.stationId=''"><option value="" disabled>所属线体</option><option v-for="line in deviceLines" :key="line.id" :value="line.id">{{ line.name }}</option></select><select v-model="equipmentForm.stationId" required><option value="" disabled>所属站位</option><option v-for="station in deviceStations" :key="station.id" :value="station.id">{{ station.name }}</option></select><button>新增设备</button></form><div class="table-wrap"><table class="equipment-table"><thead><tr><th>编号</th><th>名称</th><th>类别</th><th>班组</th><th>线体</th><th>站位</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="!filteredEquipment.length"><td colspan="8" class="equipment-empty">没有符合当前筛选条件的设备</td></tr><tr v-for="item in filteredEquipment" :key="item.id"><template v-if="editingEquipmentId===item.id"><td><input v-model.trim="equipmentDraft.code"></td><td><input v-model.trim="equipmentDraft.name"></td><td><input v-model.trim="equipmentDraft.category"></td><td><select v-model="equipmentDraft.orgUnitId" @change="equipmentDraft.lineId='';equipmentDraft.stationId=''"><option v-for="team in teams" :key="team.id" :value="team.id">{{ team.name }}</option></select></td><td><select v-model="equipmentDraft.lineId" @change="equipmentDraft.stationId=''"><option v-for="line in editDeviceLines" :key="line.id" :value="line.id">{{ line.name }}</option></select></td><td><select v-model="equipmentDraft.stationId"><option v-for="station in editDeviceStations" :key="station.id" :value="station.id">{{ station.name }}</option></select></td><td><select v-model="equipmentDraft.status"><option value="ACTIVE">启用</option><option value="DISABLED">停用</option></select></td><td><div class="edit-actions"><button class="table-button" @click="saveEquipment(item)">保存</button><button class="table-button muted" @click="editingEquipmentId=''">取消</button></div></td></template><template v-else><td>{{ item.code }}</td><td><strong>{{ item.name }}</strong></td><td>{{ item.category }}</td><td>{{ item.orgName }}</td><td>{{ item.lineName }}</td><td>{{ item.stationName }}</td><td><span :class="['status',item.status.toLowerCase()]">{{ item.status==='ACTIVE'?'启用':'停用' }}</span></td><td><div class="edit-actions"><button class="table-button" @click="editEquipment(item)">修改</button><button class="table-button" @click="toggleEquipment(item)">{{ item.status==='ACTIVE'?'停用':'启用' }}</button></div></td></template></tr></tbody></table></div></section>
        <div class="catalog-grid"><section class="panel"><div class="panel-head"><div><h3>班次生效版本</h3><p>默认白班08:30–20:30，夜班20:30–次日08:30。</p></div></div><form class="stack-form" @submit.prevent="createShift"><select v-model="shiftForm.code"><option value="DAY">白班 DAY</option><option value="NIGHT">夜班 NIGHT</option></select><input v-model.trim="shiftForm.name" placeholder="班次名称" required><div><input v-model="shiftForm.startsAt" type="time" required><input v-model="shiftForm.endsAt" type="time" required></div><input v-model="shiftForm.effectiveFrom" type="date" required><button>保存新版本</button></form></section><section class="panel"><div class="panel-head"><div><h3>法定节假日日历</h3><p>系统默认导入中国大陆法定节假日，管理员可单日覆盖。</p></div></div><form class="stack-form" @submit.prevent="saveCalendar"><input v-model="calendarForm.date" type="date" required><select v-model="calendarForm.dayType"><option value="HOLIDAY">法定节假日</option><option value="WORKDAY">调休工作日</option></select><input v-model.trim="calendarForm.name" placeholder="节日/调休名称" required><button>保存日历配置</button></form></section></div>
      </template>

      <template v-if="active==='rules'"><section class="panel"><div class="panel-head"><div><h3>积分规则版本</h3><p>仅系统管理员可编辑并直接发布；部长只读查看历史和当前版本。</p></div><form v-if="isAdmin" class="compact-form" @submit.prevent="createVersion"><input v-model.trim="versionName" placeholder="版本号，如 2026.09" required><button>新建草稿</button></form></div><div class="version-list"><div v-for="version in ruleVersions" :key="version.id" :class="{selected:selectedVersion?.id===version.id}" @click="selectRuleVersion(version)"><strong>{{ version.version }}</strong><span :class="['status',version.status.toLowerCase()]">{{ label(version.status) }}</span><small>{{ version.effectiveAt||'尚未生效' }}</small><button v-if="isAdmin&&version.status==='DRAFT'" @click.stop="publishVersion(version)">直接发布</button></div></div></section><section v-if="selectedVersion" class="panel"><div class="panel-head"><div><h3>{{ selectedVersion.version }} 规则明细</h3><p>已发布规则不可修改，历史评分始终引用原版本。</p></div></div><form v-if="isAdmin&&selectedVersion.status==='DRAFT'" class="rule-form" @submit.prevent="addRule"><input v-model.trim="ruleForm.code" placeholder="规则编号" required><input v-model.trim="ruleForm.title" placeholder="规则名称" required><select v-model="ruleForm.type"><option value="BASE">基础分</option><option value="BONUS">加分</option><option value="PENALTY">扣分</option><option value="D_GRADE">D级规则</option></select><input v-if="ruleForm.type!=='D_GRADE'" v-model.number="ruleForm.score" type="number" step="1" placeholder="整数分值" required><input v-model.number="ruleForm.monthlyCap" type="number" step="1" placeholder="月度封顶"><input v-model="ruleForm.effectiveFrom" type="date" required><input v-model="ruleForm.effectiveTo" type="date"><button>添加规则</button></form><div class="table-wrap"><table><thead><tr><th>编号</th><th>名称</th><th>类型</th><th>分值</th><th>月度封顶</th><th>生效范围</th><th>审核路径</th></tr></thead><tbody><tr v-for="item in rules" :key="item.id"><td>{{ item.code }}</td><td><strong>{{ item.title }}</strong></td><td>{{ label(item.type) }}</td><td>{{ item.score??'-' }}</td><td>{{ item.capPolicy.monthlyCap??'-' }}</td><td>{{ item.effectiveFrom }} 至 {{ item.effectiveTo||'长期' }}</td><td>{{ label(item.approvalFlow.firstNode||'') }}</td></tr></tbody></table></div></section></template>

      <template v-if="active==='audit'"><section class="panel"><div class="panel-head"><div><h3>操作审计日志</h3><p>包含人员、排班、规则、异常、导出及账号安全操作。</p></div><button class="secondary" @click="loadAdministration">刷新</button></div><div class="audit-list"><div v-for="item in audit" :key="item.id"><span class="audit-icon">记</span><div><strong>{{ item.action }}</strong><small>{{ item.targetType }} · {{ item.actorName||'系统任务' }}</small></div><time>{{ new Date(item.createdAt).toLocaleString() }}</time><code>{{ item.requestId }}</code></div></div></section></template>

      <template v-if="active==='tasks'"><section class="panel"><div class="panel-head"><h2>需要我处理</h2><button @click="loadTasks">刷新待办</button></div><div class="workflow-tabs"><button @click="taskFilter='all'">全部待办</button><button @click="taskFilter='overdue'">逾期异常</button></div><p v-if="!shownTasks.length&&!shownIncidents.length">当前没有此类待办</p><article v-for="item in shownTasks" :key="item.id" class="workflow-item"><h3>{{item.targetName}} · {{label(item.caseType)}}</h3><p>{{item.description}}</p><p>{{label(item.status)}} · 发生于 {{localTime(item.occurredAt)}}</p><button @click="reviewCase(item,'APPROVE')">审核通过</button> <button class="secondary" @click="reviewCase(item,'RETURN')">退回修改</button> <button class="secondary" @click="reviewCase(item,'REJECT')">否决</button></article><article v-for="item in shownIncidents" :key="item.id" class="workflow-item"><h3>{{item.incidentNo}} · {{item.lineName}} / {{item.stationName}}</h3><div v-for="statement in item.statements.filter((s:any)=>['SUBMITTED','OVERDUE'].includes(s.status))" :key="statement.id"><h4>{{statement.responsibleName}} · {{label(statement.status)}}</h4><p>{{statement.phenomenon||'尚未提交说明'}} · 截止 {{localTime(statement.dueAt)}}</p><template v-if="isSupervisor&&statement.status==='SUBMITTED'"><button @click="reviewStatement(statement,'APPROVE')">查看并审核</button> <button class="secondary" @click="reviewStatement(statement,'RETURN')">退回修改</button></template><p v-else>请在小程序设备异常中处理该逾期说明。</p></div><button class="secondary" @click="switchPage('incidents');openDossier(item.id)">查看异常档案</button></article></section></template>
      <template v-if="active==='messages'"><section class="panel"><div class="panel-head"><h2>我的消息</h2><button :disabled="inboxBusy" @click="loadMessages()">刷新</button></div><label><input type="checkbox" v-model="unreadOnly" @change="loadMessages()">只看未读</label><p v-if="!inbox.length">{{inboxBusy?'加载中…':'暂无消息'}}</p><article v-for="item in inbox" :key="item.id" class="workflow-item"><h3>{{item.readAt?'':'● '}}{{item.title}}</h3><p>{{item.content}}</p><p>{{localTime(item.createdAt)}}</p><button @click="openMessage(item)">查看相关事项</button></article><button v-if="inboxMore" :disabled="inboxBusy" @click="loadMessages(true)">加载更早消息</button></section></template>

    <BusinessForm v-if="businessForm" :key="businessForm.path" :spec="businessForm" @close="businessForm=null" @saved="formSaved"/>
    </main>
  </div>
</template>
